import { tags } from "typia";

import { IShoppingMallSeller } from "./IShoppingMallSeller";

/**
 * Aggregated moderation metrics grouped by seller.
 *
 * Each instance reflects how many review reports and moderation actions are
 * associated with a particular seller’s catalog for the selected time range,
 * enabling governance and account management teams to identify high-risk or
 * high-volume sellers.
 *
 * This DTO is only used in internal analytics contexts and does not expose
 * customer identity or raw review text.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallReviewModerationBySeller = {
  /**
   * Summary information for the seller whose reviews and reports are
   * aggregated in this record.
   *
   * The summary provides the seller identifier and key display fields (such
   * as name and basic status) so that analytics dashboards can render seller
   * context without additional API calls.
   */
  seller: IShoppingMallSeller.ISummary;

  /**
   * Number of distinct reviews associated with this seller that were reported
   * during the selected time range.
   *
   * This metric helps identify sellers whose products attract a
   * disproportionate number of problematic reviews.
   */
  reportedReviewCount: number & tags.Type<"int32">;

  /**
   * Total number of review reports associated with this seller’s catalog in
   * the selected time range.
   *
   * A single review may generate multiple reports; this metric counts the raw
   * report entries regardless of duplication at review level.
   */
  reportCount: number & tags.Type<"int32">;

  /**
   * Total number of review moderation actions taken on this seller’s reviews
   * in the selected time range.
   *
   * This includes any action recorded in
   * shopping_mall_review_moderation_actions that can be attributed to reviews
   * belonging to the seller.
   */
  moderationActionCount: number & tags.Type<"int32">;
};
